package com.system.recovery.service;
import com.system.recovery.dto.*; import com.system.recovery.model.*; import org.springframework.stereotype.Service; import java.math.BigDecimal; import java.util.*;
@Service public class BatchRunner { private final RecoveryDecisionService decisions; public BatchRunner(RecoveryDecisionService d){decisions=d;}
 public Map<String,Object> run(int count){int soft=0,recovered=0,falsePositive=0; BigDecimal risk=BigDecimal.ZERO,revenue=BigDecimal.ZERO; int[] curve=new int[97]; Random random=new Random(42); String[] codes={"GATEWAY_TIMEOUT","GATEWAY_5XX","CARD_EXPIRED","CARD_STOLEN_BLOCKED","FRAUD_HARD_BLOCK","INSUFFICIENT_FUNDS","DO_NOT_HONOR","OTP_3DS_FAILED","RISK_SOFT_HOLD"}; for(int i=0;i<count;i++){String code=codes[random.nextInt(codes.length)]; PaymentFailedEvent e=new PaymentFailedEvent(UUID.randomUUID(),code,code); var result=decisions.decide(e); if(result.bucket()==FailureBucket.SOFT){soft++; BigDecimal amount=result.signalBundle().orderValue();risk=risk.add(amount); int hours=result.decision().delayHours();curve[Math.min(96,Math.max(1,hours))]++; boolean success=result.decision().action()==RecoveryAction.RETRY_SILENT && random.nextDouble()<.55; if(success){recovered++;revenue=revenue.add(amount);} if(result.decision().requiresHumanApproval()&&!success)falsePositive++;}} Map<String,Object> out=new LinkedHashMap<>();out.put("failed_payments",count);out.put("soft_declines",soft);out.put("recovery_percent",soft==0?0:100.0*recovered/soft);out.put("false_positive_percent",soft==0?0:100.0*falsePositive/soft);out.put("revenue_recovered",revenue);out.put("revenue_at_risk",risk);out.put("recovery_curve",curve); System.out.println("BATCH METRICS SUMMARY");System.out.println("Recovery %: "+out.get("recovery_percent"));System.out.println("False Positive %: "+out.get("false_positive_percent"));System.out.println("Revenue Recovered: "+revenue);return out;}}
